import XCTest

@testable import CodeConnect

/// **The New session steps against the daemon's own bytes:** minor 29 (a
/// repository's checkouts, and starting in a worktree) and minor 30 (browsing
/// and making folders).
///
/// `minor-29-wire.json` and `minor-30-wire.json` are what ccd emits
/// (`fixtures/claude/`, regenerated by ccd's tests and copied here byte for
/// byte), so the shapes these tests read are the shapes the computer writes.
@MainActor
final class StartFlowWireTests: XCTestCase {

    // MARK: Harness

    private func wire(_ minor: Int) throws -> [String: JSONValue] {
        let url = try XCTUnwrap(
            Bundle(for: type(of: self)).url(forResource: "minor-\(minor)-wire", withExtension: "json"))
        return try XCTUnwrap(
            try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
    }

    private func frame(_ minor: Int, _ key: String) throws -> ServerMessage {
        let value = try XCTUnwrap(try wire(minor)[key], "no \(key) in minor-\(minor)-wire.json")
        return try JSONDecoder().decode(ServerMessage.self, from: Data(value.canonicalJSONString.utf8))
    }

    private func encoded(_ message: ClientMessage) throws -> JSONValue {
        try JSONDecoder().decode(JSONValue.self, from: JSONEncoder().encode(message))
    }

    private func capabilities(_ minor: Int) throws -> Capabilities {
        let advertised = try XCTUnwrap(try wire(minor)["hello_ack_capabilities"])
        return try JSONDecoder().decode(Capabilities.self, from: Data(advertised.canonicalJSONString.utf8))
    }

    private final class Sent {
        var sent: [ClientMessage] = []

        var listings: [(requestID: String, path: String?, showHidden: Bool)] {
            sent.compactMap {
                guard case .listFolder(let id, let path, let hidden) = $0 else { return nil }
                return (id, path, hidden)
            }
        }
    }

    private func model() throws -> (AppModel, Sent) {
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("start-flow-\(UUID().uuidString)")
        addTeardownBlock { try? FileManager.default.removeItem(at: root) }
        let model = AppModel(
            cache: EventCache(root: root),
            codexSpentLedger: CodexSpentLedger(
                defaults: UserDefaults(suiteName: "cc.tests.\(UUID().uuidString)")!))
        model.connection.simulateConnectedForTesting()
        model.connection.simulateCapabilitiesForTesting(try capabilities(30), minor: 30)
        let wire = Sent()
        model.connection.sendStub = { message in
            MainActor.assumeIsolated { wire.sent.append(message) }
        }
        addTeardownBlock { @MainActor in model.scenePhaseChanged(to: .background) }
        return (model, wire)
    }

    private func settle() async {
        for _ in 0..<5 { await Task.yield() }
    }

    // MARK: Capabilities

    /// Both are advertised from minor 29 and 30 on, and absent before.
    func testTheStepsAreOfferedOnlyWhereAdvertised() throws {
        XCTAssertTrue(try capabilities(29).startsInWorktrees)
        XCTAssertTrue(try capabilities(30).startsInWorktrees)
        XCTAssertTrue(try capabilities(30).browsesFolders)
        let url = try XCTUnwrap(Bundle(for: type(of: self)).url(forResource: "minor-28-wire", withExtension: "json"))
        let old = try XCTUnwrap(
            try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue?["hello_ack_capabilities"])
        let older = try JSONDecoder().decode(Capabilities.self, from: Data(old.canonicalJSONString.utf8))
        XCTAssertFalse(older.startsInWorktrees)
        XCTAssertFalse(older.browsesFolders)
    }

    // MARK: Minor 29

    func testAStartInAWorktreeEncodesAsTheDaemonReadsIt() throws {
        let root = try wire(29)
        XCTAssertEqual(
            try encoded(.getProjectGit(path: "/tmp/ccd-minor-29/app")), root["get_project_git_request"])
        let checkout = StartWorktree(
            path: "/tmp/ccd-minor-29/app-review", branch: "review/ui", dirty: false, missing: false)
        let cases: [(String, String, StartPlace)] = [
            ("start_session_existing_request", "claude", .existing(checkout)),
            ("start_session_branch_request", "codex", .branch("feature/search")),
            ("start_session_new_request", "claude", .new("fix-login")),
        ]
        for (key, agent, place) in cases {
            XCTAssertEqual(
                try encoded(
                    .startSession(
                        requestID: "r1", path: "/tmp/ccd-minor-29/app", agent: agent, prompt: nil, worktree: place)),
                root[key], key)
        }
    }

    func testARepositoryDecodesWithItsCheckoutsAndBranches() throws {
        guard case .projectGit(let path, let git?) = try frame(29, "project_git") else {
            return XCTFail("not a repository's answer")
        }
        XCTAssertEqual(path, "/tmp/ccd-minor-29/app")
        XCTAssertEqual(git.worktrees.first?.path, path)
        XCTAssertEqual(git.worktrees.first?.dirty, true)
        XCTAssertTrue(git.worktrees.contains { $0.missing })
        XCTAssertEqual(git.branches, ["feature/search", "bugfix-12"])
        XCTAssertFalse(git.branchesTruncated)
        XCTAssertEqual(git.checkout(at: path), git.worktrees.first)

        guard case .projectGit(_, nil) = try frame(29, "project_git_not_a_repository") else {
            return XCTFail("a folder outside git has no repository")
        }
    }

    /// Where the computer knows the folder it says so; a new Claude Code
    /// worktree's is Claude's to make.
    func testAStartedWorktreeSaysItsFolder() throws {
        for (key, cwd) in [
            ("start_existing_started", "/tmp/ccd-minor-29/app-review"),
            ("start_branch_started", "/tmp/ccd-minor-29/app/.claude/worktrees/feature+search"),
            ("start_new_codex_started", "/tmp/ccd-minor-29/app/.claude/worktrees/fix-login"),
        ] {
            guard case .startSessionResult(_, .started(_, let said)) = try frame(29, key) else {
                return XCTFail(key)
            }
            XCTAssertEqual(said, cwd, key)
        }
        guard case .startSessionResult(_, .started(_, nil)) = try frame(29, "start_new_claude_started") else {
            return XCTFail("a new Claude worktree has no folder yet")
        }
        for key in ["start_branch_failed_checked_out", "start_new_codex_failed_exists", "start_new_failed_invalid_name"] {
            guard case .startSessionResult(_, .failed(.launchFailed, let detail)) = try frame(29, key) else {
                return XCTFail(key)
            }
            XCTAssertFalse(detail.isEmpty, key)
        }
    }

    /// The bar's folder is the computer's word once it has started.
    func testTheStartedFolderIsTheOneTheComputerNamed() async throws {
        let (model, _) = try model()
        let project = StartProject(
            path: "/tmp/ccd-minor-29/app", name: "app", lastUsed: Date(), lastAgent: nil, gitBranch: "main",
            exists: true)
        let id = model.startSession(project, place: .branch("feature/search"), agent: .codex, prompt: "")
        XCTAssertNil(model.starter.starts[id]?.folder)
        guard case .startSessionResult(_, let outcome) = try frame(29, "start_branch_started") else {
            return XCTFail()
        }
        model.connection.injectForTesting(.startSessionResult(requestID: id, outcome: outcome))
        XCTAssertEqual(model.starter.starts[id]?.folder, "/tmp/ccd-minor-29/app/.claude/worktrees/feature+search")
    }

    // MARK: Minor 30

    func testBrowsingRequestsEncodeAsTheDaemonReadsThem() throws {
        let root = try wire(30)
        XCTAssertEqual(
            try encoded(.listFolder(requestID: "b1", path: "/tmp/ccd-minor-30/src", showHidden: false)),
            root["list_folder_request"])
        XCTAssertEqual(
            try encoded(.listFolder(requestID: "b1", path: "/tmp/ccd-minor-30/src", showHidden: true)),
            root["list_folder_hidden_request"])
        XCTAssertEqual(
            try encoded(.listFolder(requestID: "b1", path: nil, showHidden: false)), root["list_folder_home_request"])
        XCTAssertEqual(
            try encoded(.createFolder(requestID: "c1", parent: "/tmp/ccd-minor-30/src", name: "new-app")),
            root["create_folder_request"])
        XCTAssertEqual(
            try encoded(
                .startSession(requestID: "r1", path: "/tmp/ccd-minor-30/src/new-app", agent: "claude", prompt: nil)),
            root["start_session_unlisted_request"])
    }

    func testListingsDecodeWithTheComputersOwnWords() throws {
        guard case .folderListing("b1", let listing) = try frame(30, "folder_listing") else { return XCTFail() }
        XCTAssertEqual(listing.path, "/tmp/ccd-minor-30/src")
        XCTAssertEqual(listing.folders, ["app", "semi;"])
        XCTAssertNil(listing.error)
        guard case .folderListing(_, let hidden) = try frame(30, "folder_listing_hidden") else { return XCTFail() }
        XCTAssertEqual(hidden.folders, [".config", "app", "semi;"])
        for (key, words) in [
            ("folder_listing_unreadable", "No such file or directory"),
            ("folder_listing_relative", "\"src\" is not an absolute path"),
        ] {
            guard case .folderListing(_, let refused) = try frame(30, key) else { return XCTFail(key) }
            XCTAssertEqual(refused.error, words, key)
            XCTAssertTrue(refused.folders.isEmpty, key)
        }
    }

    func testAMadeFolderSaysSoAndARefusalSaysWhy() throws {
        guard case .createFolderResult("c1", nil) = try frame(30, "create_folder_created") else {
            return XCTFail("created")
        }
        for (key, words) in [
            ("create_folder_failed_exists", "File exists"),
            ("create_folder_failed_not_one_name", "\"a/b\" is not a single folder name"),
        ] {
            guard case .createFolderResult(_, let refusal) = try frame(30, key) else { return XCTFail(key) }
            XCTAssertEqual(refusal, words, key)
        }
    }

    /// Only the answer to the latest ask for a folder is shown; after a
    /// reconnect an unanswered ask goes again, under a fresh id.
    func testTheLatestListingIsShownAndALostOneIsAskedAgain() async throws {
        let (model, sent) = try model()
        let request = StartFolderRequest(path: "/tmp/ccd-minor-30/src", showHidden: false)
        model.listFolder(request)
        model.listFolder(request)
        await settle()
        XCTAssertEqual(sent.listings.count, 2)
        let (stale, latest) = (sent.listings[0].requestID, sent.listings[1].requestID)
        XCTAssertNotEqual(stale, latest)

        let listing = StartFolderListing(path: "/tmp/ccd-minor-30/src", folders: ["old"], truncated: false, error: nil)
        model.connection.injectForTesting(.folderListing(requestID: stale, listing: listing))
        XCTAssertNil(model.starter.listings[request], "an earlier ask's answer is not shown")

        let hello = """
            {"type":"hello_ack","protocol_version":\(Wire.protocolVersion),"protocol_minor":30,\
            "server_time":"2026-11-04T03:00:00.000Z","capabilities":\(try wire(30)["hello_ack_capabilities"]!.canonicalJSONString)}
            """
        model.connection.injectForTesting(try JSONDecoder().decode(ServerMessage.self, from: Data(hello.utf8)))
        await settle()
        XCTAssertEqual(sent.listings.count, 3)
        let again = sent.listings[2]
        XCTAssertEqual(again.path, request.path)
        XCTAssertNotEqual(again.requestID, latest)

        guard case .folderListing(_, let answer) = try frame(30, "folder_listing") else { return XCTFail() }
        model.connection.injectForTesting(.folderListing(requestID: again.requestID, listing: answer))
        XCTAssertEqual(model.starter.listings[request]?.folders, ["app", "semi;"])
    }

    /// A repository read the link lost is asked for again after a reconnect;
    /// an answered one is not.
    func testALostRepositoryReadIsAskedAgain() async throws {
        let (model, sent) = try model()
        model.projectGit("/tmp/ccd-minor-29/app")
        model.projectGit("/tmp/ccd-minor-29/notes")
        await settle()
        model.connection.injectForTesting(try frame(29, "project_git_not_a_repository"))
        let hello = """
            {"type":"hello_ack","protocol_version":\(Wire.protocolVersion),"protocol_minor":30,\
            "server_time":"2026-11-04T03:00:00.000Z","capabilities":\(try wire(30)["hello_ack_capabilities"]!.canonicalJSONString)}
            """
        model.connection.injectForTesting(try JSONDecoder().decode(ServerMessage.self, from: Data(hello.utf8)))
        await settle()
        let asked = sent.sent.compactMap { message -> String? in
            guard case .getProjectGit(let path) = message else { return nil }
            return path
        }
        XCTAssertEqual(asked, ["/tmp/ccd-minor-29/app", "/tmp/ccd-minor-29/notes", "/tmp/ccd-minor-29/app"])
    }

    /// A folder or a repository asked for while a redial has no capabilities
    /// yet is asked for once the handshake is back.
    func testWhatIsAskedDuringARedialIsAskedAfterIt() async throws {
        let (model, sent) = try model()
        model.connection.stop()
        model.listFolder(StartFolderRequest(path: "/tmp/ccd-minor-30/src", showHidden: false))
        model.projectGit("/tmp/ccd-minor-29/app")
        await settle()
        let before = sent.sent.count
        let hello = """
            {"type":"hello_ack","protocol_version":\(Wire.protocolVersion),"protocol_minor":30,\
            "server_time":"2026-11-04T03:00:00.000Z","capabilities":\(try wire(30)["hello_ack_capabilities"]!.canonicalJSONString)}
            """
        model.connection.injectForTesting(try JSONDecoder().decode(ServerMessage.self, from: Data(hello.utf8)))
        await settle()
        let after = sent.sent.dropFirst(before)
        XCTAssertTrue(
            after.contains {
                if case .listFolder(_, "/tmp/ccd-minor-30/src"?, false) = $0 { return true } else { return false }
            }, "the folder is listed once the link is back")
        XCTAssertTrue(
            after.contains { if case .getProjectGit("/tmp/ccd-minor-29/app") = $0 { return true } else { return false } },
            "the repository is read once the link is back")
    }

    /// A start keeps its place through a resend.
    func testAStartKeepsItsPlaceThroughAResend() async throws {
        let (model, sent) = try model()
        let project = StartProject(
            path: "/tmp/ccd-minor-29/app", name: "app", lastUsed: Date(), lastAgent: nil, gitBranch: "main",
            exists: true)
        let id = model.startSession(project, place: .new("fix-login"), agent: .claude, prompt: "")
        await settle()
        let hello = """
            {"type":"hello_ack","protocol_version":\(Wire.protocolVersion),"protocol_minor":30,\
            "server_time":"2026-11-04T03:00:00.000Z","capabilities":\(try wire(30)["hello_ack_capabilities"]!.canonicalJSONString)}
            """
        model.connection.injectForTesting(try JSONDecoder().decode(ServerMessage.self, from: Data(hello.utf8)))
        await settle()
        let starts = sent.sent.compactMap { message -> StartPlace? in
            guard case .startSession(let request, _, _, _, let place) = message, request == id else { return nil }
            return place
        }
        XCTAssertEqual(starts, [.new("fix-login"), .new("fix-login")])
    }
}
